using UnityEngine;
using System;

public class DemoApp:MonoBehaviour {
 [Serializable]public class Settings{public int count=12;public float spacing=2;public int formation=0;public bool split=false;public int airframe=0;public int[] airframes;}
 [Serializable]public class TrainingReport{public float seconds;public float formationError;public int boundaryFrames;public int selectedDrone;public Settings settings;}
 Settings cfg=new Settings();Transform[] drones;Vector3[] velocities;Camera cam;Vector3 leader=new Vector3(0,3,0);int selected;bool fpv,paused;string status="Ready";float elapsed,error;int boundaryHits;
 float[] speeds={4,7,2};string[] names={"Trainer","Racer","Heavy"};
 void Start(){DemoWorld.Light();DemoWorld.Box("Field",new Vector3(0,-.2f,0),new Vector3(100,.2f,100),new Color(.12f,.25f,.2f));for(int i=0;i<5;i++){DemoWorld.Box("GateLeft",new Vector3(-3,2,8+i*8),new Vector3(.3f,4,.3f),Color.yellow);DemoWorld.Box("GateRight",new Vector3(3,2,8+i*8),new Vector3(.3f,4,.3f),Color.yellow);}cam=DemoWorld.Camera(new Vector3(15,18,-22));Build();}
 void Build(){if(cfg.airframes==null||cfg.airframes.Length!=cfg.count){var oldProfiles=cfg.airframes;cfg.airframes=new int[cfg.count];for(int k=0;k<cfg.count;k++)cfg.airframes[k]=oldProfiles!=null&&k<oldProfiles.Length?oldProfiles[k]:k%3;}if(drones!=null)foreach(var d in drones)if(d)Destroy(d.gameObject);drones=new Transform[cfg.count];velocities=new Vector3[cfg.count];for(int i=0;i<drones.Length;i++){drones[i]=DemoWorld.Box("Drone-"+i,new Vector3(i%4*2,3,i/4*2),new Vector3(.8f,.2f,.8f),Color.HSVToRGB((float)i/drones.Length,.7f,1)).transform;var nose=DemoWorld.Box("Nose",drones[i].position+Vector3.forward*.5f,new Vector3(.2f,.1f,.4f),Color.white);nose.transform.SetParent(drones[i],true);}selected=Mathf.Clamp(selected,0,drones.Length-1);}
 Vector3 Offset(int i){float s=cfg.spacing;if(cfg.formation==1){float a=i*Mathf.PI*2/drones.Length;return new Vector3(Mathf.Cos(a),0,Mathf.Sin(a))*s*drones.Length/4;}if(cfg.formation==2)return new Vector3((i%2==0?-1:1)*(i/2)*s,0,-i/2*s);return new Vector3((i%4-1.5f)*s,0,i/4*s)+(cfg.split?(i%2==0?Vector3.left:Vector3.right)*6:Vector3.zero);}
 void Update(){float dt=Mathf.Min(Time.deltaTime,.05f);if(!paused){elapsed+=dt;Vector3 input=new Vector3(Input.GetAxis("Horizontal"), (Input.GetKey(KeyCode.E)?1:0)-(Input.GetKey(KeyCode.Q)?1:0),Input.GetAxis("Vertical"));leader+=input*speeds[cfg.airframes[selected]]*dt;var old=leader;leader=new Vector3(Mathf.Clamp(leader.x,-45,45),Mathf.Clamp(leader.y,1,20),Mathf.Clamp(leader.z,-45,45));if(old!=leader)boundaryHits++;error=0;for(int i=0;i<drones.Length;i++){Vector3 target=leader+Offset(i);if(fpv&&i==selected)target=leader;Vector3 separation=Vector3.zero;for(int j=0;j<drones.Length;j++)if(i!=j){var diff=drones[i].position-drones[j].position;float d=diff.magnitude;if(d<1.2f)separation+=diff/(d*d+.05f);}var desired=Vector3.ClampMagnitude((target-drones[i].position)*2+separation*3,speeds[cfg.airframes[i]]);velocities[i]=Vector3.MoveTowards(velocities[i],desired,8*dt);drones[i].position+=velocities[i]*dt;if(velocities[i].sqrMagnitude>.1f)drones[i].rotation=Quaternion.Slerp(drones[i].rotation,Quaternion.LookRotation(velocities[i]),dt*3);error+=Vector3.Distance(target,drones[i].position);}error/=drones.Length;}
 if(fpv){cam.transform.position=drones[selected].TransformPoint(new Vector3(0,.3f,.3f));cam.transform.rotation=drones[selected].rotation;}else{cam.transform.position=leader+new Vector3(15,18,-22);cam.transform.LookAt(leader);}}
 void OnGUI(){GUILayout.BeginArea(new Rect(10,10,340,650),GUI.skin.box);GUILayout.Label("DRONE SIM | kinematic training MVP");GUILayout.Label("WASD: leader move | Q/E: altitude");cfg.formation=GUILayout.SelectionGrid(cfg.formation,new[]{"Grid","Ring","V"},3);GUILayout.Label("Selected drone type:");cfg.airframes[selected]=GUILayout.SelectionGrid(cfg.airframes[selected],names,3);if(GUILayout.Button("Add drone")&&cfg.count<64){cfg.count++;Build();}if(GUILayout.Button("Remove drone")&&cfg.count>1){cfg.count--;Build();}GUILayout.Label("Spacing: "+cfg.spacing.ToString("F1"));cfg.spacing=GUILayout.HorizontalSlider(cfg.spacing,1.5f,5);cfg.split=GUILayout.Toggle(cfg.split,"Split groups (grid mode)");if(GUILayout.Button("FPV / external"))fpv=!fpv;if(GUILayout.Button("Next drone"))selected=(selected+1)%drones.Length;if(GUILayout.Button(paused?"Resume":"Pause"))paused=!paused;if(GUILayout.Button("Save training report")){DemoWorld.Save("drone-training.json",JsonUtility.ToJson(new TrainingReport{seconds=elapsed,formationError=error,boundaryFrames=boundaryHits,selectedDrone=selected,settings=cfg},true));status="Training report saved";}if(GUILayout.Button("Save swarm preset")){DemoWorld.Save("swarm.json",JsonUtility.ToJson(cfg));status="Saved";}if(GUILayout.Button("Load preset")){try{var s=DemoWorld.Load("swarm.json");if(s!=null){var next=JsonUtility.FromJson<Settings>(s);if(next.count<1||next.count>64||next.airframe<0||next.airframe>2||next.formation<0||next.formation>2||float.IsNaN(next.spacing)||next.spacing<1.5f||next.spacing>5)throw new Exception("Invalid preset");if(next.airframes!=null)foreach(int profile in next.airframes)if(profile<0||profile>=speeds.Length)throw new Exception("Invalid airframe profile");cfg=next;Build();}}catch(Exception e){status=e.Message;}}GUILayout.Label($"Time {elapsed:F1}s | formation error {error:F2}m\nBoundary frames {boundaryHits} | drone {selected}\n{status}");GUILayout.Label("No real flight controller or aerodynamics yet.");GUILayout.EndArea();}
}
